(()=>{'use strict';
const loadPrivacy=()=>new Promise(resolve=>{const p=document.createElement('script');p.src='./privacy-file.js';p.onload=resolve;p.onerror=resolve;document.body.appendChild(p)});
const waitForQR=()=>new Promise((resolve,reject)=>{let n=0;const tick=()=>{if(typeof window.qrcode==='function')return resolve();if(++n>120)return reject(Error('Local QR generator unavailable'));setTimeout(tick,100)};tick()});
const patchedRuntime=async()=>{
  const r=await fetch('./runtime.js',{cache:'no-store'});
  if(!r.ok)throw Error('runtime.js unavailable');
  let source=await r.text();
  source=source.replace("const q=qrcode(0,'M');q.addData(text,'Byte');q.make();box.innerHTML=q.createSvgTag(5,4);", "const q=qrcode(0,'L');q.addData(text,'Byte');q.make();box.innerHTML=q.createImgTag(6,4,'AWEP2PAWE QR');");
  source=source.replace("const q=qrcode(40,'L');q.addData(text,'Byte');q.make();box.innerHTML=q.createImgTag(6,4,'AWEP2PAWE QR');", "const q=qrcode(0,'L');q.addData(text,'Byte');q.make();box.innerHTML=q.createImgTag(6,4,'AWEP2PAWE QR');");
  source=source.replace("function downloadQR(){const svg=$('#qr svg');if(!svg)return toast('Generate a QR first');const u=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(svg)],{type:'image/svg+xml'})),a=document.createElement('a');a.href=u;a.download=`awe-chat-${S.chatId||'invite'}.svg`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}", "function downloadQR(){const img=$('#qr img');if(!img?.src)return toast('Generate a QR first');const a=document.createElement('a');a.href=img.src;a.download=`awe-chat-${S.chatId||'invite'}.png`;document.body.appendChild(a);a.click();a.remove()}");
  const replacement=`async function scan(){const d=$('#scanner'),v=$('#scan-video');if(!d||!v)return;try{d.showModal();$('#scanner-status').textContent='Starting local camera scanner…';const finish=async raw=>{if(!raw)return;stopScanner();try{d.close()}catch{}await decodeInput(raw)};if('BarcodeDetector'in window){try{const detector=new BarcodeDetector({formats:['qr_code']});const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1920},height:{ideal:1080}},audio:false});v.srcObject=stream;await v.play();window.__aweLocalScanLoop=true;const loop=async()=>{if(!window.__aweLocalScanLoop||!d.open)return;try{const codes=await detector.detect(v);if(codes[0]?.rawValue){window.__aweLocalScanLoop=false;await finish(codes[0].rawValue);return}}catch{}requestAnimationFrame(loop)};loop();$('#scanner-status').textContent='Point the camera at the QR code…';return}catch{}}if(typeof QrScanner==='function'){const scanner=new QrScanner(v,result=>{const raw=typeof result==='string'?result:result?.data;if(raw){try{scanner.stop();scanner.destroy()}catch{}finish(raw)}},{preferredCamera:'environment',maxScansPerSecond:15,highlightScanRegion:true,highlightCodeOutline:true,onDecodeError:()=>{}});window.__aweQrScanner=scanner;await scanner.start();$('#scanner-status').textContent='Point the camera at the QR code…';return}throw Error('No local QR scanner available')}catch(e){stopScanner();try{d.close()}catch{}const m=String(e?.message||e);$('#scanner-status').textContent='Camera unavailable — choose a QR image.';toast(/permission|denied/i.test(m)?'Camera permission denied':(/secure context|https/i.test(m)?'Camera requires HTTPS':'Camera could not start'))}}
async function scanImage(file){if(!file)return;try{$('#scanner-status').textContent='Reading QR locally…';let raw=null;if('BarcodeDetector'in window){try{const detector=new BarcodeDetector({formats:['qr_code']});const bmp=await createImageBitmap(file);const codes=await detector.detect(bmp);bmp.close?.();raw=codes[0]?.rawValue||null}catch{}}if(!raw&&typeof QrScanner==='function'){const result=await QrScanner.scanImage(file,{returnDetailedScanResult:true,alsoTryWithoutScanRegion:true});raw=typeof result==='string'?result:result?.data}if(!raw)throw Error('No QR code found');stopScanner();try{$('#scanner').close()}catch{}await decodeInput(raw)}catch(e){toast('No readable QR code found');$('#scanner-status').textContent='No QR found — choose a clear QR image.'}}
function send(`;
  const re=/async function scan\(\)\{[\s\S]*?function send\(/;
  if(!re.test(source))throw Error('Runtime scanner section not found');
  source=source.replace(re,replacement);
  const blob=URL.createObjectURL(new Blob([source],{type:'text/javascript'}));
  const s=document.createElement('script');s.src=blob;s.onload=()=>setTimeout(()=>URL.revokeObjectURL(blob),1000);s.onerror=()=>{URL.revokeObjectURL(blob);throw Error('Patched runtime failed')};document.body.appendChild(s);
};
const start=async()=>{if(window.__aweRuntimeStarted)return;window.__aweRuntimeStarted=true;try{await loadPrivacy();await waitForQR();await patchedRuntime()}catch(e){const status=document.querySelector('#qr-status');if(status)status.textContent='Startup error — refresh the page';const toast=document.querySelector('#toast');if(toast){toast.textContent='AWEP2PAWE could not start: '+(e?.message||e);toast.classList.add('show')}}};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();
